package com.silva.edu.finances.domain.dtos.request;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;

import java.math.BigDecimal;

/**
 * Optional payload for confirming a pending recurrence. When {@code value} is provided the
 * amount is applied only to the occurrence generated by this confirmation; the recurrence
 * template keeps its original value.
 */
public record ConfirmRecurrenceRequest(
        @DecimalMin(value = "0.01") @Digits(integer = 15, fraction = 4) BigDecimal value
) {
}
